p='src/services/auth-service.js'
s=open(p).read()
s=s.replace("import { query } from '../db.js';","import { query, update } from '../db.js';")
s+='''
// Stamps last_login_at on the active user with this email.
// Calls back with the updated user, or null if no active user matches.
export function recordLogin(email, callback) {
  findByEmail(email, (err, user) => {
    if (err) return callback(err);
    if (!user) return callback(null, null);
    update('users', user.id, { last_login_at: new Date().toISOString() }, callback);
  });
}
'''
open(p,'w').write(s)
p='tests/auth-service.test.js'
s=open(p).read()
s=s.replace("import { findByEmail, isActive }","import { findByEmail, isActive, recordLogin }")
s+='''
test('recordLogin sets last_login_at to now on the active user', (t, done) => {
  const before = Date.now();
  recordLogin('grace@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user.email, 'grace@example.com');
    const stamped = Date.parse(user.last_login_at);
    assert.ok(stamped >= before && stamped <= Date.now());
    findByEmail('grace@example.com', (err2, stored) => {
      assert.equal(err2, null);
      assert.equal(stored.last_login_at, user.last_login_at);
      done();
    });
  });
});

test('recordLogin does not touch soft-deleted users', (t, done) => {
  recordLogin('alan@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});
'''
open(p,'w').write(s)
EOF
